const items = $input.all();

// Si no hay resultados
if (!items || items.length === 0 || !items[0].json.Nombre) {
  return [{
    json: {
      // null → Typebot toma el camino "no tiene packs" (H-23)
      nombre_cliente: null,
      tarifa_internet: null,
      servicios_internet: null
    }
  }];
}

// 1. Formatear Nombre (Primera letra de cada palabra en mayúscula)
const nombreRaw = items[0].json.Nombre || '';
const nombreFormateado = nombreRaw
  .toLowerCase()
  .replace(/(^|\s)\S/g, l => l.toUpperCase());

// 2. Obtener y formatear la Tarifa con emoji (ej: 🏷️ Residencial)
const tarifaRaw = items[0].json.TarifaDescripcion || 'Tarifa Única';
const tarifaInternet = "🏷️ " + tarifaRaw;

// 3. Formatear cada pack/servicio de internet con su emoji 🔹
const listaServicios = items
  .map(item => item.json.PackDescripcion)
  .filter(Boolean)
  .map(desc => "  🔹 " + desc)
  .join('\n');

return [{
  json: {
    nombre_cliente: nombreFormateado,
    tarifa_internet: tarifaInternet,
    servicios_internet: listaServicios || 'Sin packs adicionales'
  }
}];

const items = $input.all();

let lineas = [];

items.forEach(item => {
  const tarifaCodigo = String(item.json.Tarifa || '').trim().toUpperCase();
  const descripcionRaw = String(item.json.Descripcion_Internet || '').trim().toUpperCase();
  const precio = Math.round(item.json.Precio_Total || 0).toLocaleString('es-AR');

  // FILTRO ESTRICTO: Si la tarifa o la descripción es de 25mb, 50mb o el PACK1 que no querés, lo salteamos por completo
  if (
    tarifaCodigo.includes('25') || 
    tarifaCodigo.includes('50') || 
    tarifaCodigo === 'PACK1' ||
    descripcionRaw.includes('25.MB') || 
    descripcionRaw.includes('25 MB') || 
    descripcionRaw.includes('50 MB')
  ) {
    return; // Esto los "borra" para que ni siquiera entren a la lista
  }

  // Limpiamos los nombres comerciales para el resto
  let nombreComercial = item.json.Descripcion_Internet || item.json.Tarifa;

  if (tarifaCodigo.includes('100') || descripcionRaw.includes('100MB')) nombreComercial = 'Plan 100 MB + TV Cable';
  else if (tarifaCodigo.includes('300') || descripcionRaw.includes('300MB')) nombreComercial = 'Plan 300 MB + TV Cable';
  else if (tarifaCodigo.includes('500') || descripcionRaw.includes('500MB')) nombreComercial = 'Plan 500 MB + TV Cable';

  lineas.push("🔹 *" + nombreComercial + "*\n    ➔ *$ " + precio + "* / mes");
});

const mensajeFinal = "📺 *PACKS INTERNET + TV CABLE*\n\n" + lineas.join("\n\n");

return [{
  json: {
    texto_tarifas: mensajeFinal
  }
}];

const items = $input.all();

let lineas = [];

items.forEach(item => {
  const rawDesc = item.json.Descripcion || '';
  const precio = Math.round(item.json.Precio_Total || 0).toLocaleString('es-AR');

  let nombreComercial = rawDesc;

  // Emprolijamos los nombres para la vista del usuario
  if (rawDesc.includes('FUTBOL')) nombreComercial = 'Pack Fútbol Premium';
  else if (rawDesc.includes('HBO')) nombreComercial = 'HBO Max Full';
  else if (rawDesc.includes('UNIVERSAL')) nombreComercial = 'Universal Plus';
  else if (rawDesc.includes('HOT GO')) nombreComercial = 'Pack Hot Go';
  else if (rawDesc.includes('APP SENSA TV')) nombreComercial = 'Sensa TV (SOLO)';

  lineas.push("📺 *" + nombreComercial + "*\n   ➔ *$" + precio + "* / mes");
});

const mensajeFinal = "⭐ *PACKS ADICIONALES Y PREMIUM*\n\n" + lineas.join("\n\n");

return [{
  json: {
    texto_tarifas: mensajeFinal
  }
}];

const items = $input.all();

let resultado = {
  encontrado: false,
  nombre: "",
  codigo_tarifa_energia: "",
  tarifa_energia: "Sin servicio",
  codigo_tarifa_internet: "",
  tarifa_internet: "Sin servicio",
  codigo_tarifa_agua: "",
  tarifa_agua: "Sin servicio"
};

if (items.length > 0 && items[0].json.Nombre) {
  resultado.encontrado = true;
  resultado.nombre = items[0].json.Nombre;

  items.forEach(item => {
    const data = item.json;

    const servicio = (data.Servicio || '')
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");

    if (servicio === 'energia') {
      resultado.codigo_tarifa_energia = data.CodigoTarifa || '';
      resultado.tarifa_energia = data.Tarifa;
    } else if (servicio === 'internet') {
      resultado.codigo_tarifa_internet = data.CodigoTarifa || '';
      resultado.tarifa_internet = data.Tarifa;
    } else if (servicio === 'agua') {
      resultado.codigo_tarifa_agua = data.CodigoTarifa || '';
      resultado.tarifa_agua = data.Tarifa;
    }
  });
}

return [{ json: resultado }];

// 1. Se leen las 4 consultas SQL
const energia = $('tarifas_comerciales_energia').all().map(i => i.json);
const agua = $('tarifas_comerciales_agua').all().map(i => i.json);
const internet = $('tarifas_comerciales_internet').all().map(i => i.json);
const sepelio = $('tarifas_comerciales_Sepelio').all().map(i => i.json);

// 2. Formateo de Moneda
function fmt(valor) {
  if (valor === undefined || valor === null) return "$ 0,00";
  return new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: 'ARS',
    minimumFractionDigits: 2
  }).format(valor).replace('ARS', '$').trim();
}

// 3. Plantilla con estética y formato Markdown
const textoMensaje = `💵 *VALORES Y COSTOS DE CONEXIÓN*
───────────────────────────

⚡ *Energía Eléctrica*
• Monofásica Residencial (T1R): *${fmt(energia[1]?.DerechoConexion)}*
• Trifásica Residencial (T1R TRIF): *${fmt(energia[1]?.DerechoConexionTrif)}*
• Monofásica Comercial (T1GBC): *${fmt(energia[0]?.DerechoConexion)}*
